mapper.insert:
INSERT INTO inquiry_comment (
    inquiry_comment_no, inquiry_no, member_no, content, created_at, delete_yn
)
VALUES (
    seq_inquiry_comment.nextval, #{inquiryNo}, #{memberNo}, #{content}, SYSTIMESTAMP, 'N'
)

mapper.update:
UPDATE inquiry_comment
SET delete_yn = 'Y'
WHERE inquiry_comment_no = #{commentNo}

mapper.select:
SELECT inquiry_no
FROM inquiry_comment
WHERE inquiry_comment_no = #{commentNo}
